    root->left->right = temp->left;
    temp->left = root->left;
    root->left = temp;
    root->left->height = 1 + std::max((root->left->left ? root->left->left->height : 0), (root->left->right ? root->left->right->height : 0));
    root->height = 1 + std::max((root->left ? root->left->height : 0), (root->right ? root->right->height : 0));
    TreeNode* temp2 = root;
    root->right = temp2->left;
    temp2->left = root;
    root = temp2;
    root->height = 1 + std::max((root->left ? root->left->height : 0), (root->right ? root->right->height : 0));
    root->left->height = 1 + std::max((root->left->left ? root->left->left->height : 0), (root->left->right ? root->left->right->height : 0));
}
// Right Left Case
if (balance < -1 && (root->right != nullptr) && (root->right->height - (root->right->left ? root->right->left->height : 0)) > 0) {
    TreeNode* temp = root->right->left;
    root->right->left = temp->right;
    temp->right = root->right;
    root->right = temp;
    root->right->height = 1 + std::max((root->right->left ? root->right->left->height : 0), (root->right->right ? root->right->right->height : 0));
    root->height = 1 + std::max((root->left ? root->left->height : 0), (root->right ? root->right->height : 0));
    TreeNode* temp2 = root;
    root->left = temp2->right;
    temp2->right = root;
    root = temp2;
    root->height = 1 + std::max((root->left ? root->left->height : 0), (root->right ? root->right->height : 0));
    root->right->height = 1 + std::max((root->right->left ? root->right->left->height : 0), (root->right->right ? root->right->right->height : 0));
}
